-- n8n node: Execute a SQL query in Postgres
-- Query parameters are in the workflow; n8n expressions are not standalone SQL.
WITH p AS (SELECT $1::jsonb j), idx AS (SELECT subject_id FROM mimiciv_hosp.admissions WHERE hadm_id=(SELECT (j->>'hadm_id')::int FROM p)), matched AS (
 SELECT DISTINCT v.hadm_id,v.outcome_in_hospital_mortality AS h,v.outcome_mortality_30d AS m,v.outcome_readmission_30d AS r,v.outcome_los_hours AS los
 FROM mimiciv.agent_demographics_fast v JOIN mimiciv_hosp.admissions a ON a.hadm_id=v.hadm_id CROSS JOIN p CROSS JOIN idx
 WHERE a.subject_id<>idx.subject_id AND p.j->'matching_features'->>'age' IS NOT NULL AND p.j->'matching_features'->>'sex' IS NOT NULL AND (p.j->'matching_features'->>'age' IS NULL OR v.age_years BETWEEN (p.j->'matching_features'->>'age')::numeric-5 AND (p.j->'matching_features'->>'age')::numeric+5) AND (p.j->'matching_features'->>'sex' IS NULL OR v.sex=(p.j->'matching_features'->>'sex')::text) AND (p.j->'matching_features'->>'admission_type' IS NULL OR v.admission_type=(p.j->'matching_features'->>'admission_type')::text) AND (p.j->'matching_features'->>'unit_type' IS NULL OR v.unit_type=(p.j->'matching_features'->>'unit_type')::text) AND (p.j->'matching_features'->>'has_chf' IS NULL OR v.has_chf=(p.j->'matching_features'->>'has_chf')::boolean) AND (p.j->'matching_features'->>'has_diabetes' IS NULL OR v.has_diabetes=(p.j->'matching_features'->>'has_diabetes')::boolean) AND (p.j->'matching_features'->>'has_copd' IS NULL OR v.has_copd=(p.j->'matching_features'->>'has_copd')::boolean) AND (p.j->'matching_features'->>'has_ckd' IS NULL OR v.has_ckd=(p.j->'matching_features'->>'has_ckd')::boolean) AND (p.j->'matching_features'->>'has_cancer' IS NULL OR v.has_cancer=(p.j->'matching_features'->>'has_cancer')::boolean) AND (p.j->'matching_features'->>'has_immunosupp' IS NULL OR v.has_immunosupp=(p.j->'matching_features'->>'has_immunosupp')::boolean) AND (p.j->'matching_features'->>'has_neutropenia' IS NULL OR v.has_neutropenia=(p.j->'matching_features'->>'has_neutropenia')::boolean) AND (p.j->'matching_features'->>'has_pneumonia' IS NULL OR v.has_pneumonia=(p.j->'matching_features'->>'has_pneumonia')::boolean) AND (p.j->'matching_features'->>'has_cvc_inf' IS NULL OR v.has_cvc_inf=(p.j->'matching_features'->>'has_cvc_inf')::boolean)
), agg AS (SELECT count(*) AS n,jsonb_build_object('denominator',count(h) FILTER(WHERE h IN(0,1)),'events',count(*) FILTER(WHERE h=1),'value',avg(h) FILTER(WHERE h IN(0,1))) AS h,jsonb_build_object('denominator',count(m) FILTER(WHERE m IN(0,1)),'events',count(*) FILTER(WHERE m=1),'value',avg(m) FILTER(WHERE m IN(0,1))) AS m,jsonb_build_object('denominator',count(r) FILTER(WHERE r IN(0,1)),'events',count(*) FILTER(WHERE r=1),'value',avg(r) FILTER(WHERE r IN(0,1))) AS r,jsonb_build_object('denominator',count(los) FILTER(WHERE los>=0),'events',NULL,'value',avg(los/24.0) FILTER(WHERE los>=0)) AS l FROM matched)
SELECT jsonb_build_object('contract_version','mas_original_severity_v3','case_id',p.j->>'case_id','role','demographics','similar_patients_found',agg.n,'cohort_unit','admissions','same_patient_excluded',true,'matching_features',p.j->'matching_features','probability_unit','fraction','los_unit','days','los_statistic','mean','mortality_30d_origin','discharge','endpoints',jsonb_build_object('in_hospital_mortality',agg.h,'mortality_30d',agg.m,'readmission_30d',agg.r,'los_days',agg.l)) AS cohort FROM p CROSS JOIN agg;
